args.newString:
export default async function Home() {
  // Use fetch with no-store cache option to opt out of static prerendering
  // This ensures the timestamp is generated on each request
  const response = await fetch('https://api.example.com/health', {
    cache: 'no-store'
  });

  // Get current server timestamp
  const serverTimestamp = new Date().toISOString();

  return (
    <main style={{ padding: '2rem', fontFamily: 'Arial, sans-serif' }}>
      <h1>Server Timestamp</h1>
      <p>Current server time (dynamic, changes on each request):</p>
      <div style={{ 
        marginTop: '1rem', 
        padding: '1rem', 
        backgroundColor: '#f0f0f0', 
        borderRadius: '8px',
        fontSize: '1.2rem',
        fontWeight: 'bold'
      }}>
        {serverTimestamp}
      </div>
      <p style={{ marginTop: '1rem', fontSize: '0.9rem', color: '#666' }}>
        This timestamp is generated server-side on each request, not prerendered at build time.
      </p>
    </main>
  );
}

